var t = document.getElementById('t'), p = document.getElementById('panel'), s = document.getElementById('status');
t.addEventListener('click', function () {
  var open = t.getAttribute('aria-expanded') === 'true';
  t.setAttribute('aria-expanded', String(!open));
  p.hidden = open;
  t.textContent = open ? 'Show details' : 'Hide details';
  s.textContent = open ? 'Details hidden' : 'Details shown';
});

document.getElementById('b').addEventListener('click', function () {
  var p = document.querySelector('p[hidden], p[data-was-hidden]');
  p.hidden = !p.hidden; p.setAttribute('data-was-hidden', '');
});

document.querySelectorAll('.buy').forEach(function (b) {
  b.addEventListener('click', function () {
    var d = b.dataset;
    document.getElementById('out').textContent = 'Product #' + d.productId + ': ' + d.name + ' costs ' + Number(d.price).toLocaleString();
  });
});
